<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$s=db()->prepare('SELECT t.*,p.name,p.unique_identifier,f.shop_name from_shop,tu.shop_name to_shop FROM product_transfers t JOIN products p ON p.id=t.product_id JOIN users f ON f.id=t.from_user_id JOIN users tu ON tu.id=t.to_user_id WHERE t.from_user_id=? OR t.to_user_id=? ORDER BY t.transferred_at DESC');$s->execute([$u['id'],$u['id']]);out(['success'=>true,'transfers'=>$s->fetchAll()]);
